import{_ as o,c as a,o as t,a2 as r}from"./chunks/framework.PGES7OoM.js";const d=JSON.parse(`{"title":"Register Your Curvy ID","description":"","frontmatter":{"rawMarkdown":"# Register Your Curvy ID\\n\\nTo set up your Curvy Wallet, the first step is to create your account. Every account gets a Curvy ID.\\n\\nA Curvy ID is like a personal email address or an internet domain that other people can use to privately send funds to you.\\n\\n::: warning\\n\\nCurvy App is a self-custody wallet. That means you control your account. If you lose access, nobody, not even Curvy, can recover it.\\nSo please read the following steps carefully and follow them to stay safe.\\n\\nCurvy never stores your password or private keys.\\n\\n:::\\n\\n## Step 1: Create your account\\n\\nOpen [app.curvy.box](https://app.curvy.box) and choose **Create account**. If you already have an account, choose **Log in** instead.\\n\\nYou are then asked how you want to sign in. There are two options:\\n\\n- **Use a passkey**: your face, fingerprint, or device PIN unlocks the account.\\n- **Use a wallet**: an existing Ethereum wallet plus a password you create.\\n\\nCurvy picks an available Curvy ID for you and shows it once the account is ready.\\nYou can change it at any time under **Settings → Profile**; your old name is released when you do.\\n\\nA good Curvy ID is:\\n\\n- Easy to pronounce and spell\\n- Unambiguous\\n- Your alias\\n\\nYou are free to even set your full name as the Curvy ID, as it will only be used when\\naddressing payments to you. The underlying privacy protocol ensures that only the sender knows to whom the funds are addressed.\\n\\n## Step 2a: Register using a Passkey\\n\\nChoose **Use a passkey** and approve the prompt from your browser or password manager ([more on passkeys](https://www.eff.org/deeplinks/2023/10/what-passkey)).\\n\\nCurvy derives your keys from the passkey, so the passkey provider has to support the WebAuthn PRF extension.\\nMajor platform passkeys (Google, Apple) and password managers such as 1Password do. If yours does not, the app tells you so during sign-up and you can use a wallet instead.\\n\\nIf your passkey is synced to your platform's cloud, you will also be able to log in on desktops using your mobile device.\\n\\n> [!TIP]\\n> Passkeys are a good and secure way to access the Curvy App on both desktop and mobile devices without needing a cryptocurrency wallet.\\n\\n## Step 2b: Register using an existing wallet\\n\\n> [!NOTE]\\n>\\n> - If you are on **desktop**, ensure you have a compatible wallet browser extension or a WalletConnect supported wallet.\\n> - If you are on **mobile**, ensure you are opening Curvy through a wallet browser, or using a WalletConnect supported wallet.\\n\\nTo get started:\\n\\n- Choose **Use a wallet** and pick the wallet you'd like to connect (an Ethereum / EVM wallet such as MetaMask or Rabby, or any wallet through WalletConnect).\\n  The wallet you connect becomes the key to your Curvy account. Combined with the password you set in the next step, it provides the most secure way to access and manage your Curvy web app.\\n\\n- Next, create a password (at least 8 characters). Curvy combines your wallet signature with this password to generate your private keys, ensuring your account is secure and fully self-custodial.\\n\\n> [!TIP]\\n> Ensure you keep your password safe and back up your Curvy keys right after creating your account. If you lose access to your wallet or forget your password, your backup keys will be the only way to recover your funds.\\n\\n- Curvy will then ask your wallet to sign a message. This isn't a blockchain transaction; it's a local action that enables your wallet to generate the keys needed to manage your Curvy account and funds. This happens entirely in your browser. Your private keys remain on your device and are never uploaded, shared, or stored anywhere else.\\n\\n> [!NOTE]\\n> To learn more about how the authentication process in Curvy works, you can refer to the [Curvy ID](/for-the-curious/building-blocks/curvy-id) in the \\"Curvy for the curious\\" section.\\n","rawMarkdownPath":"/_raw/for-users/register-your-curvy-id.md","rawMarkdownTitle":"Register Your Curvy ID","rawMarkdownUrl":"https://docs.curvy.box/_raw/for-users/register-your-curvy-id.md"},"headers":[],"relativePath":"for-users/register-your-curvy-id.md","filePath":"for-users/register-your-curvy-id.md","lastUpdated":1791449043000}`),s={name:"for-users/register-your-curvy-id.md"};function n(u,e,l,i,y,c){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="register-your-curvy-id" tabindex="-1">Register Your Curvy ID <a class="header-anchor" href="#register-your-curvy-id" aria-label="Permalink to &quot;Register Your Curvy ID&quot;">​</a></h1><p>To set up your Curvy Wallet, the first step is to create your account. Every account gets a Curvy ID.</p><p>A Curvy ID is like a personal email address or an internet domain that other people can use to privately send funds to you.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Curvy App is a self-custody wallet. That means you control your account. If you lose access, nobody, not even Curvy, can recover it. So please read the following steps carefully and follow them to stay safe.</p><p>Curvy never stores your password or private keys.</p></div><h2 id="step-1-create-your-account" tabindex="-1">Step 1: Create your account <a class="header-anchor" href="#step-1-create-your-account" aria-label="Permalink to &quot;Step 1: Create your account&quot;">​</a></h2><p>Open <a href="https://app.curvy.box" target="_blank" rel="noreferrer">app.curvy.box</a> and choose <strong>Create account</strong>. If you already have an account, choose <strong>Log in</strong> instead.</p><p>You are then asked how you want to sign in. There are two options:</p><ul><li><strong>Use a passkey</strong>: your face, fingerprint, or device PIN unlocks the account.</li><li><strong>Use a wallet</strong>: an existing Ethereum wallet plus a password you create.</li></ul><p>Curvy picks an available Curvy ID for you and shows it once the account is ready. You can change it at any time under <strong>Settings → Profile</strong>; your old name is released when you do.</p><p>A good Curvy ID is:</p><ul><li>Easy to pronounce and spell</li><li>Unambiguous</li><li>Your alias</li></ul><p>You are free to even set your full name as the Curvy ID, as it will only be used when addressing payments to you. The underlying privacy protocol ensures that only the sender knows to whom the funds are addressed.</p><h2 id="step-2a-register-using-a-passkey" tabindex="-1">Step 2a: Register using a Passkey <a class="header-anchor" href="#step-2a-register-using-a-passkey" aria-label="Permalink to &quot;Step 2a: Register using a Passkey&quot;">​</a></h2><p>Choose <strong>Use a passkey</strong> and approve the prompt from your browser or password manager (<a href="https://www.eff.org/deeplinks/2023/10/what-passkey" target="_blank" rel="noreferrer">more on passkeys</a>).</p><p>Curvy derives your keys from the passkey, so the passkey provider has to support the WebAuthn PRF extension. Major platform passkeys (Google, Apple) and password managers such as 1Password do. If yours does not, the app tells you so during sign-up and you can use a wallet instead.</p><p>If your passkey is synced to your platform&#39;s cloud, you will also be able to log in on desktops using your mobile device.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Passkeys are a good and secure way to access the Curvy App on both desktop and mobile devices without needing a cryptocurrency wallet.</p></div><h2 id="step-2b-register-using-an-existing-wallet" tabindex="-1">Step 2b: Register using an existing wallet <a class="header-anchor" href="#step-2b-register-using-an-existing-wallet" aria-label="Permalink to &quot;Step 2b: Register using an existing wallet&quot;">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li>If you are on <strong>desktop</strong>, ensure you have a compatible wallet browser extension or a WalletConnect supported wallet.</li><li>If you are on <strong>mobile</strong>, ensure you are opening Curvy through a wallet browser, or using a WalletConnect supported wallet.</li></ul></div><p>To get started:</p><ul><li><p>Choose <strong>Use a wallet</strong> and pick the wallet you&#39;d like to connect (an Ethereum / EVM wallet such as MetaMask or Rabby, or any wallet through WalletConnect). The wallet you connect becomes the key to your Curvy account. Combined with the password you set in the next step, it provides the most secure way to access and manage your Curvy web app.</p></li><li><p>Next, create a password (at least 8 characters). Curvy combines your wallet signature with this password to generate your private keys, ensuring your account is secure and fully self-custodial.</p></li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Ensure you keep your password safe and back up your Curvy keys right after creating your account. If you lose access to your wallet or forget your password, your backup keys will be the only way to recover your funds.</p></div><ul><li>Curvy will then ask your wallet to sign a message. This isn&#39;t a blockchain transaction; it&#39;s a local action that enables your wallet to generate the keys needed to manage your Curvy account and funds. This happens entirely in your browser. Your private keys remain on your device and are never uploaded, shared, or stored anywhere else.</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>To learn more about how the authentication process in Curvy works, you can refer to the <a href="/for-the-curious/building-blocks/curvy-id.html">Curvy ID</a> in the &quot;Curvy for the curious&quot; section.</p></div>',24)])])}const h=o(s,[["render",n]]);export{d as __pageData,h as default};
